def find_largest_number(lst):
    if len(lst) == 0:
        return None
    elif len(lst) == 1:
        return lst[0]
    else:
        largest = lst[0]
        for num in lst[1:]:
            if num > largest:
                largest = num
        return largest

# Test the function
numbers = [4, 2, 9, 6, 5, 1, 8, 3, 7]
print("Largest Number:", find_largest_number(numbers))
